        cursor->v.cn[0] = 255;
        cursor->v.cn[1] = 255;
        cursor->v.cn[2] = 255;
        cursor->v.cn[3] = alpha;
        cursor->v.flag = 0;
        cursor++;
        cursor->v.ob[0] = (s32)(position.x - offsetX);
        cursor->v.ob[1] = (s32)position.y;
        cursor->v.ob[2] = (s32)(position.z - offsetZ);
        cursor->v.tc[0] = tag;
        cursor->v.tc[1] = texture[low];
        cursor->v.cn[0] = 255;
        cursor->v.cn[1] = 255;
        cursor->v.cn[2] = 255;
        cursor->v.cn[3] = 0;
        cursor->v.flag = 0;
